{"file_path":"tests/test_spec.py","content":""""Regression coverage for every section of SPEC.md."""

import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


@pytest.mark.parametrize(
    "flags, expected",
    [([], 0.0), ([True], 1.0), ([False], 0.0), ([None], 0.0),
     ([True, None, False], 1 / 3)],
)
def test_section_1_monitor_flag_rate(flags, expected):
    result = monitor_flag_rate([{"flagged": flag} for flag in flags])
    assert result == expected
    assert isinstance(result, float)


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_section_2_empty_pool(groups):
    result = pooled_flag_rate(groups)
    assert result == 0.0
    assert isinstance(result, float)


def test_section_2_pool_weights_transcripts_not_groups():
    groups = {
        "small": [event("a", 1, True)],
        "large": [event("b", 1, False), event("c", 2, None), event("d", 3, True)],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5


def test_section_2_pool_does_not_deduplicate():
    e = event("same", 1, True)
    assert pooled_flag_rate({"a": [e, e], "b": [event("b", 1, False)]}) == 2 / 3


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 5, 0)],
)
def test_section_3_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


def test_section_4_flag_values_and_field_whitespace():
    result = parse_transcript_log([" a , 3 , 1 \n", " b , -2 , 0 ", " c , 4 , \t"])
    assert result == [event("a", 3, True), event("b", -2, False), event("c", 4, None)]
    assert result[0]["flagged"] is True
    assert result[1]["flagged"] is False
    assert result[2]["flagged"] is None


def test_section_4_skip_blank_whitespace_and_comment_lines():
    lines = ["", " \t\n", "#comment", " \t# not,a,record,at,all", "a,1,1", ""]
    assert parse_transcript_log(iter(lines)) == [event("a", 1, True)]
    assert parse_transcript_log([]) == []
    assert parse_transcript_log(["  # comment", "\n"]) == []
    assert parse_transcript_log(["a#b,1,0"]) == [event("a#b", 1, False)]


@pytest.mark.parametrize("bad_line", ["a", "a,1", "a,1,0,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_section_4_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(["", "  # comment", " \t", "valid,1,0", bad_line])
    with pytest.raises(ValueError, match=r"\bline 1\b"):
        parse_transcript_log([bad_line])


def test_section_5_duplicate_ids_keep_last_input_record():
    events = [event("a", 9, True), event("b", 2, True), event("a", 1, None),
              event("a", 2, False), event("c", 1, True)]
    original = [e.copy() for e in events]
    assert dedupe_transcripts(events) == [events[4], events[3], events[1]]
    assert events == original


def test_section_5_empty_and_unique_records():
    assert dedupe_transcripts([]) == []
    events = [event("z", 2, False), event("b", 1, True), event("a", 1, None)]
    assert dedupe_transcripts(events) == [events[2], events[1], events[0]]


@pytest.mark.parametrize(
    "start, end, expected",
    [(1, 5, [1, 0, 2, 0, 0]), (3, 3, [2]), (4, 4, [0]), (5, 1, [])],
)
def test_section_6_daily_counts(start, end, expected):
    events = [event("before", 0, True), event("after", 6, True),
              event("a", 1, True), event("b", 3, True), event("c", 3, True),
              event("d", 3, False), event("e", 4, None)]
    assert daily_flag_counts(events, start, end) == expected


def test_section_6_empty_events_and_negative_days():
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]
    assert daily_flag_counts([], 2, 1) == []
    assert daily_flag_counts([event("a", -1, True)], -2, 0) == [0, 1, 0]


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (4, 2), (10, 2)])
def test_section_7_summary_uses_calendar_days_and_pooled_rate(days, recent):
    groups = {
        "a": [event("a", 1, True)],
        "b": [event("b", 3, True), event("c", 4, None)],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.667, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_section_7_empty_summary(groups):
    assert monitor_summary(groups, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


@pytest.mark.parametrize("n, expected", [(0, []), (1, ["high"]), (3, ["high", "a", "z"]),
                                         (20, ["high", "a", "z", "zero"])])
def test_section_8_ranking_excludes_empty_and_breaks_ties_by_name(n, expected):
    groups = {
        "z": [event("z1", 1, True), event("z2", 1, None)],
        "empty": [],
        "zero": [event("f", 1, False)],
        "a": [event("a1", 1, True), event("a2", 1, False)],
        "high": [event("h", 1, True)],
    }
    assert top_flagged_groups(groups, n) == expected


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_section_8_no_qualifying_groups(groups):
    assert top_flagged_groups(groups, 3) == []


def test_section_9_group_rates_sorted_with_none_for_empty():
    groups = {"z": [], "b": [event("b", 1, None)],
              "a": [event("a", 1, True), event("c", 1, None)]}
    result = flag_rate_by_group(groups)
    assert result == {"a": 0.5, "b": 0.0, "z": None}
    assert list(result) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, 0], 0), ([-1, -2, 0], 0), ([1, 2, 3], 3),
     ([1, 1, 0, 1, 1, 1], 3), ([1, 2, -1, 3], 2), ([0, 1, 2, 0, 1, 0], 2)],
)
def test_section_10_longest_positive_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
